Rules.InvariantScript:
If(IsBlank(varHistFilter), Set(varHistFilter, "All"));
Clear(colAssetTimeline);

// 1. Registration of the asset. ForAll over a Filter yields zero or one row by
//    itself, with no If that has to mix a record with a blank.
Collect(
    colAssetTimeline,
    ForAll(
        Filter(Equipment_Assets, 'Id (ID)' = varCurrentAsset.'Id (ID)') As a,
        {
            SortKey: DateDiff(Date(2000, 1, 1), a.Gemaakt, TimeUnit.Minutes),
            EventTime: Text(a.Gemaakt, DateTimeFormat.ShortDateTime24),
            Kind: "Registered",
            Who: Coalesce(a.'Gemaakt door'.DisplayName, "?"),
            Summary: "Asset registered",
            Detail: Coalesce(a.DeviceName, "")
        }
    )
);

// 2. Moves
Collect(
    colAssetTimeline,
    ForAll(
        Filter(Equipment_MovementLog, Title = varCurrentAsset.Titel) As m,
        {
            SortKey: DateDiff(Date(2000, 1, 1), m.TimeStamp, TimeUnit.Minutes),
            EventTime: Text(m.TimeStamp, DateTimeFormat.ShortDateTime24),
            Kind: If(
                m.ActionType.Value = "Handover/Assignment",
                "Handover",
                "Move"
            ),
            Who: Coalesce(m.MovedBy.DisplayName, "?"),
            Summary: If(
                m.ActionType.Value = "Handover/Assignment",
                "Assigned to " & Coalesce(m.AssignedUser.DisplayName, "?"),
                Coalesce(m.FromLocation.Value, "unknown") & "   to   " & Coalesce(m.ToLocation.Value, "unknown")
            ),
            Detail: Coalesce(m.ActionType.Value, "")
        }
    )
);

// 3. Reported issues
Collect(
    colAssetTimeline,
    ForAll(
        Filter(Equipment_Tickets, Title = varCurrentAsset.Titel) As t,
        {
            SortKey: DateDiff(Date(2000, 1, 1), t.ReportedDate, TimeUnit.Minutes),
            EventTime: Text(t.ReportedDate, DateTimeFormat.ShortDateTime24),
            Kind: "Issue",
            Who: Coalesce(t.ReportedBy.DisplayName, "?"),
            Summary: Coalesce(t.TypeMaintenance.Value, "Problem reported") &
                If(IsBlank(t.Severity.Value), "", "   (" & t.Severity.Value & ")"),
            Detail: Coalesce(t.Description, "")
        }
    )
);

// 4. Resolutions, as a separate moment on the timeline
Collect(
    colAssetTimeline,
    ForAll(
        Filter(
            Equipment_Tickets,
            Title = varCurrentAsset.Titel,
            !IsBlank(ResolvedDate)
        ) As r,
        {
            SortKey: DateDiff(Date(2000, 1, 1), r.ResolvedDate, TimeUnit.Minutes),
            EventTime: Text(r.ResolvedDate, DateTimeFormat.ShortDate),
            Kind: "Resolved",
            Who: Coalesce(r.ResolvedBy.DisplayName, "?"),
            Summary: "Resolved: " & Coalesce(r.TypeMaintenance.Value, "problem"),
            Detail: Coalesce(r.ResolutionNotes, "No resolution notes recorded")
        }
    )
);

// 5. Bookings
Collect(
    colAssetTimeline,
    ForAll(
        Filter(Equipment_Bookings, Title = varCurrentAsset.Titel) As b,
        {
            SortKey: DateDiff(Date(2000, 1, 1), b.StartDate, TimeUnit.Minutes),
            EventTime: Text(b.StartDate, DateTimeFormat.ShortDate),
            Kind: "Booking",
            Who: Coalesce(b.ReservedBy.DisplayName, "?"),
            Summary: "Booked until " & Text(b.EndDate, DateTimeFormat.ShortDate),
            Detail: Coalesce(b.ProjectCode, "") &
                If(IsBlank(b.BookingStatus.Value), "", "   |   " & b.BookingStatus.Value)
        }
    )
);

// 6. Maintenance
Collect(
    colAssetTimeline,
    ForAll(
        Filter(
            Equipment_Assets,
            'Id (ID)' = varCurrentAsset.'Id (ID)',
            !IsBlank(LastMaintenanceDate)
        ) As mt,
        {
            SortKey: DateDiff(Date(2000, 1, 1), mt.LastMaintenanceDate, TimeUnit.Minutes),
            EventTime: Text(mt.LastMaintenanceDate, DateTimeFormat.ShortDate),
            Kind: "Maintenance",
            Who: "-",
            Summary: "Maintenance carried out",
            Detail: If(
                IsBlank(mt.NextMaintenanceDue),
                "",
                "Next maintenance " & Text(mt.NextMaintenanceDue, DateTimeFormat.ShortDate)
            )
        }
    )
)
